export async function seedDemoContent(prisma: PrismaClient) {
  for (const material of DEMO_MATERIALS) {
    const course = await prisma.course.upsert({
      where: { slug: material.slug },
      update: {
        title: material.title,
        description: material.description,
        type: material.type,
        level: material.level,
        tag: material.tag,
        coverImage: material.coverImage,
        published: true,
      },
      create: {
        slug: material.slug,
        title: material.title,
        description: material.description,
        type: material.type,
        level: material.level,
        tag: material.tag,
        coverImage: material.coverImage,
        published: true,
      },
    });

    const keptModuleIds: string[] = [];

    let moduleOrder = 0;
    for (const mod of material.modules) {
      const existingModule = await prisma.module.findFirst({
        where: { courseId: course.id, title: mod.title },
      });

      const moduleRecord =
        existingModule ??
        (await prisma.module.create({
          data: { courseId: course.id, title: mod.title, order: moduleOrder },
        }));

      keptModuleIds.push(moduleRecord.id);

      const keptSlugs = mod.lessons.map((lesson) => lesson.slug);

      let lessonOrder = 0;
      for (const lesson of mod.lessons) {
        await prisma.lesson.upsert({
          where: { moduleId_slug: { moduleId: moduleRecord.id, slug: lesson.slug } },
          update: {
            title: lesson.title,
            content: lesson.content,
            videoUrl: lesson.videoUrl,
            kind: lesson.kind,
            durationMinutes: lesson.durationMinutes,
            published: true,
          },
          create: {
            moduleId: moduleRecord.id,
            slug: lesson.slug,
            title: lesson.title,
            type: lesson.videoUrl ? "VIDEO" : "TEXT",
            content: lesson.content,
            videoUrl: lesson.videoUrl,
            kind: lesson.kind,
            durationMinutes: lesson.durationMinutes,
            published: true,
            order: lessonOrder,
          },
        });
        lessonOrder++;
      }

      // Remove lessons left over from a previous version of this module (renamed/removed slugs).
      await prisma.lesson.deleteMany({
        where: { moduleId: moduleRecord.id, slug: { notIn: keptSlugs } },
      });

      moduleOrder++;
    }

    // Remove modules (and their lessons, via cascade) left over from a previous
    // version of this course — e.g. a module that was later renamed.
    await prisma.module.deleteMany({
      where: { courseId: course.id, id: { notIn: keptModuleIds } },
    });
  }

  // Remove courses (and their modules/lessons, via cascade) that were dropped
  // from DEMO_MATERIALS entirely, so removing a course here actually removes it.
  const keptCourseSlugs = DEMO_MATERIALS.map((m) => m.slug);
  await prisma.course.deleteMany({
    where: { slug: { notIn: keptCourseSlugs } },
  });

  return keptCourseSlugs;
}
